/** Step gates are shared by buttons and transitions so navigation cannot bypass validation. */
export function canAdvanceStudio({step,title,uploaded=false,reviews=false,busy=false}){
 if(busy||!title?.id)return false;
 if(step===0)return ['films','series','episode'].includes(title.kind)&&(title.kind!=='episode'||!!title.series_id&&Number(title.season_number)>0&&Number(title.episode_number)>0);
 if(step===1)return uploaded||title.kind==='series';
 if(step===2)return reviews;
 return false;
}
/** One task per step. Server publishing rules remain authoritative. */
export function mountStudioWizard(root,{selected,streamEnabled=()=>false}){
 root.classList.add('studio-wizard');const fields=root.querySelector('#videoFields'),r2=root.querySelector('#r2Upload').closest('section');
 const steps=['Details','Upload','Review','Publish'];let step=0,uploaded=false,busy=false;
 const nav=document.createElement('nav');nav.className='wizard-steps';nav.setAttribute('aria-label','Publishing steps');const stage=document.createElement('h3');stage.className='wizard-stage-title';const hint=document.createElement('p');hint.className='muted';hint.setAttribute('role','status');fields.before(nav,stage,hint);
 const panels=Array.from({length:4},()=>[]);const assign=(el,index)=>{el.dataset.wizardPanel=index;panels[index].push(el);};
 const draft=root.querySelector('#videoDraft'),selector=root.querySelector('#videoTitle').closest('section'),create=document.createElement('details');create.innerHTML='<summary>Create a new movie, series, or episode</summary>';draft.before(selector,create);create.append(draft);assign(create,0);assign(selector,0);const cancelCreate=document.createElement('button');cancelCreate.type='button';cancelCreate.className='button button-secondary';cancelCreate.textContent='Cancel new title';draft.append(cancelCreate);draft.addEventListener('input',()=>{const picker=root.querySelector('#videoTitle');if(picker.value){picker.value='';picker.dispatchEvent(new Event('change'));}});cancelCreate.onclick=()=>{draft.reset();delete draft.dataset.parentSeries;root.querySelector('#draftKind').disabled=false;root.querySelector('#draftSeries').disabled=false;root.querySelector('#draftKind').dispatchEvent(new Event('change'));create.open=false;render();};draft.querySelector('[name=poster]').closest('label').hidden=true;assign(root.querySelector('#releaseMode').closest('section'),3);
 const stream=root.querySelector('#streamOptions');stream.hidden=true; // Paid upload stays available only by explicit opt-in below.
 const advanced=document.createElement('details');advanced.innerHTML='<summary>Advanced: managed Cloudflare Stream (requires paid configuration)</summary>';r2.after(advanced);advanced.append(stream);stream.hidden=false;assign(advanced,1);
 const intro=r2.querySelector('h3');intro.textContent='Upload your encoded episode or movie';const upload=document.createElement('div'),review=document.createElement('div'),publish=document.createElement('div');
 const end=r2.querySelector('#r2Status');const children=[...r2.children];for(const child of children){if(child===end)continue;if(child.id==='r2Publish')publish.append(child);else if(child.matches('label')&&child.querySelector('#r2Rights,#r2Captions'))review.append(child);else upload.append(child);}const artwork=document.createElement('label');artwork.textContent='Thumbnail (optional JPEG, up to 250 KB)';const thumbnail=document.createElement('input');thumbnail.type='file';thumbnail.accept='image/jpeg';artwork.append(thumbnail);const artworkStatus=document.createElement('p');review.append(artwork,artworkStatus);thumbnail.onchange=async()=>{try{const file=thumbnail.files[0];if(!file)return;if(file.size>250000)throw new Error('Choose a JPEG under 250 KB.');const title=selected();if(!title)throw new Error('Select an episode or movie first.');artworkStatus.textContent='Saving thumbnail…';const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=reject;reader.readAsDataURL(file);});const {apiRequest}=await import('./api-client.js');await apiRequest('/api/admin/titles/'+title.id+'/artwork',{method:'POST',body:JSON.stringify({jpeg:data})});artworkStatus.textContent='Thumbnail saved. A series inherits its first episode image.';}catch(e){artworkStatus.textContent=e.message;}};r2.prepend(upload,review,publish);assign(upload,1);assign(review,2);assign(publish,3);
 const generic=root.querySelector('#videoPublish').closest('.state-panel');const genericPublish=document.createElement('div');genericPublish.append(root.querySelector('#publishHelp'),root.querySelector('#selectParent'),root.querySelector('#videoPublish'));generic.after(genericPublish);assign(generic,2);assign(genericPublish,3);
 const summary=document.createElement('div');summary.className='wizard-summary';root.querySelector('#videoTitle').closest('section').after(summary);
 const feedback=document.createElement('p');feedback.id='wizardFeedback';feedback.setAttribute('role','status');fields.append(feedback);const footer=document.createElement('div');footer.className='studio-nav';const back=document.createElement('button'),next=document.createElement('button');back.className='button button-secondary';next.className='button button-primary';back.type=next.type='button';footer.append(back,next);fields.append(footer);
 const reviewsDone=()=>{const series=selected()?.kind==='series';return (series?['videoRights','videoCaptions']:['r2Rights','r2Captions']).every(id=>root.querySelector('#'+id).checked);};
 const render=()=>{const title=selected(),series=title?.kind==='series';if(title&&!uploaded&&!busy&&root.querySelector('#r2ProgressLabel').textContent.startsWith('Step 1:'))root.querySelector('#r2ProgressLabel').textContent='Ready to upload '+title.name;r2.hidden=step===0||series||title?.status==='published';for(let i=0;i<4;i++)for(const panel of panels[i])panel.hidden=i!==step;generic.hidden=step!==2||!series;advanced.hidden=step!==1||!streamEnabled(); // R2 review is the default video path.
  if(step===2){generic.hidden=!series;review.hidden=series;}if(step===3){publish.hidden=series||title?.status==='published';genericPublish.hidden=!series&&title?.status!=='published';}
  nav.replaceChildren(...steps.map((name,i)=>{const button=document.createElement('button');button.type='button';button.textContent=`${i+1}. ${name}`;if(i===step)button.setAttribute('aria-current','step');button.disabled=busy||i>step;button.onclick=()=>{step=i;render();};return button;}));stage.textContent=steps[step];
  hint.textContent=[ 'Create or select the exact movie, series collection, or episode you want to manage.',series?'A collection has no video file. Its episodes are uploaded separately.':'Choose the complete HLS folder. Upload progress and retry guidance appear here.','Check rights, captions, and thumbnail before publishing.','Choose a release time, then publish. Episodes appear to viewers only after their series is published.'][step];
  summary.replaceChildren();if(title){const badge=document.createElement('strong');badge.className='status-sticker '+title.status;badge.textContent=title.status==='published'?'✓ PUBLISHED':title.status==='scheduled'?'SCHEDULED':'DRAFT · NOT LIVE';const name=document.createElement('h3');name.textContent=title.name;const metadata=document.createElement('p');metadata.textContent=title.kind==='episode'?`${title.series_name||'Series'} · Season ${title.season_number} / Episode ${title.episode_number}`:title.kind==='series'?'Series collection · videos belong to its episodes':'Movie';summary.append(badge,name,metadata);const actions=document.createElement('div');actions.className='video-actions';if(series){const add=document.createElement('button');add.type='button';add.className='button button-primary';add.textContent='＋ Add episode to this series';add.disabled=busy;add.onclick=()=>root.dispatchEvent(new CustomEvent('studio:add-episode',{detail:{seriesId:title.id}}));actions.append(add);}const remove=document.createElement('button');remove.type='button';remove.className='button button-danger';remove.textContent=title.kind==='episode'?'Delete episode':title.status==='draft'?'Delete draft':'Delete title';remove.disabled=busy;remove.onclick=()=>{const note=document.createElement('p');note.className='notice';note.textContent='Remove '+title.name+' from Aether? This moves it to a recoverable archive. Video storage remains allocated.';const confirm=document.createElement('button'),keep=document.createElement('button');confirm.type=keep.type='button';confirm.className='button button-danger';keep.className='button button-secondary';confirm.textContent='Move to archive';keep.textContent='Keep title';confirm.onclick=()=>{confirm.disabled=true;root.dispatchEvent(new CustomEvent('studio:archive',{detail:{titleId:title.id}}));};keep.onclick=render;actions.replaceChildren(note,confirm,keep);};actions.append(remove);summary.append(actions);}else summary.textContent=draft.dataset.parentSeries?'Creating an episode in the locked parent series. Complete every required field and create the draft first.':'Select an existing title, or expand Create a new title below.';
  back.textContent='← Back';back.disabled=step===0||busy;next.textContent=step===0?(title?.status==='published'?'View published status →':title?.status==='scheduled'?'Manage scheduled release →':'Continue →'):step===1?'Review upload →':step===2?'Set release →':'Publish using the button above';next.hidden=step===3;next.disabled=!canAdvanceStudio({step,title,uploaded,reviews:reviewsDone(),busy});if(step===2&&!reviewsDone())hint.textContent='Complete both publishing reviews before continuing.';};
 back.onclick=()=>{step=Math.max(0,step-1);render();};next.onclick=()=>{const title=selected();if(!canAdvanceStudio({step,title,uploaded,reviews:reviewsDone(),busy}))return;if(!title){hint.textContent='Create or select a title before continuing.';return;}if(step===0&&['published','scheduled'].includes(title.status)){step=3;}else if(step===0&&title.kind==='series'){step=2;}else step=Math.min(3,step+1);render();stage.scrollIntoView({behavior:'smooth',block:'start'});};
 fields.addEventListener('studio:selection',()=>{uploaded=false;if(step===3&&selected()?.kind==='series'&&selected()?.status==='draft')step=2;render();});fields.addEventListener('change',e=>{if(e.target.matches('#r2Rights,#r2Captions,#videoRights,#videoCaptions'))render();});root.addEventListener('studio:add-episode',()=>{step=0;create.open=true;render();create.scrollIntoView({behavior:'smooth',block:'start'});});root.addEventListener('studio:draft-created',()=>{create.open=false;step=0;render();});fields.addEventListener('studio:upload-state',e=>{busy=e.detail.state==='uploading';if(e.detail.state==='complete'){uploaded=true;step=2;}if(e.detail.state==='published')step=3;render();});render();
}
